import{z as s,x as p,o as l,c as B,q as i,j as o,D as e,d as t,s as A,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"互补式 EUV","description":"","frontmatter":{"title":"互补式 EUV","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/complementary-euv.md","filePath":"litho/complementary-euv.md","lastUpdated":1791413859000}'),V={name:"litho/complementary-euv.md"};function d(m,a,U,u,c,h){const r=p("Mermaid");return l(),B("div",null,[a[2]||(a[2]=i('<h1 id="互补式-euv" tabindex="-1">互补式 EUV <a class="header-anchor" href="#互补式-euv" aria-label="Permalink to &quot;互补式 EUV&quot;">​</a></h1><div class="epigraph"><p>密集一维线继续用自对准劈节距，切块与孔用 EUV 单次补上：EUV 是互补的那一刀，不是把整层改成一张版印完。</p><footer>—— 据先进节点对 complementary lithography / EUV cut-block 的公开层策略整理，不编产能</footer></div><p><a href="/litho/euv-sapt-hybrid">上一课</a>把 EUV 与自对准写成可以叠在同一层策略里：EUV 当芯轴，或与 SAQP 共存。缺口是更具体的一种公开分法——互补式：193i（或 EUV）做出单向密线，EUV 专做 cut / block / 孔。本课钉互补，不编 wph、片成本和成品率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>混合课已经说：0.33 NA 单次仍有 \\(k_1\\) 窗，更密的鳍和金属会走 spacer。互补式把这句话收成分工：周期方向的密度交给 SADP/SAQP（套刻结构有利），终止与二维连通交给 EUV 的切和块（单次二维能力比浸没多重切更干净）。公开节点叙事里，这是「EUV 插入」的一种层策略，不是「该代所有临界层都变一张 EUV 版」。</p><p>缺口因此是切块互补，而不是重算混合课的 mandrel 光源选择。没有这层，会把「上了 NXE」读成 SAQP 与 cut 消失。</p><h3 id="互补不是对称的两次-euv" tabindex="-1">互补不是对称的两次 EUV <a class="header-anchor" href="#互补不是对称的两次-euv" aria-label="Permalink to &quot;互补不是对称的两次 EUV&quot;">​</a></h3><p>名字里的 complementary 来自一维栅格设计：线与切在功能上互补。线可以仍是浸没 SAQP，切用 EUV；或线也 EUV、切仍 EUV——那是 EUV+EUV，仍叫互补几何，但波长分工不同。必须按层声明：谁印线，谁印切。不要用一个词覆盖两种成本结构。本课不把任何一种写成唯一量产点。</p><p><span class="marginnote">初学者容易把「多重图形化」读成「在光刻机上多曝几次」。SAQP 的节距劈分靠沉积与刻蚀长出 spacer，一次曝光定 mandrel，其余几刀都在薄膜工艺里完成；光刻机工时省下来，正是把密度交给 spacer 的动机之一。</span></p><p><span class="marginnote">公开策略谈话会提到 EUV 做 via 与 cut、浸没多重做线。那是层类型语言。把它翻译成某厂某年的产能或良率，就是编造。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一层策略时列三行：mandrel/线用哪台、cut/block 用哪台、孔是否单独 EUV。互补式的典型公开组合是：1D 线 = 浸没 SAQP（或 EUV 芯轴 + spacer），2D 信息 = EUV 切/块。设计规则：线单向、拐角靠切拼出来，与纯 EUV 任意二维不同。DTCO 先于光学：布局必须是格点。</p><p>计量：线的四相 space 仍按 SAQP 课；切的套刻是 EUV 场对浸没栅，跨平台匹配进 overlay 预算。混合课警告过节点名不是波长，本课加上：同一层内也可以两种波长互补。</p><p><span class="marginnote">可以把 1D 密线想象成先织一整面栅栏：栅栏的密与直交给 spacer 自对准去保证，切与块则是拿剪刀在栅栏上剪出需要的口子。剪刀的落点自由度是二维的，恰好交给 EUV 的单次二维曝光。</span></p><h3 id="后课默认" tabindex="-1">后课默认 <a class="header-anchor" href="#后课默认" aria-label="Permalink to &quot;后课默认&quot;">​</a></h3><p>说到互补式 EUV，默认「切/块/孔用 EUV 补 1D 自对准线」，并要求声明线的波长。说到整层 EUV 单次，那是另一工作点，不要混名。产能与源功率不在本课出现。</p>',16)),(l(),o(n,null,{default:e(()=>[A(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1D%5B%221D%20%E5%AF%86%E7%BA%BF%3A%20SAQP%20%2F%20spacer%22%5D%20--%3E%20GRID%5B%22%E6%A0%BC%E7%82%B9%E7%BA%BF%E6%A0%85%22%5D%0A%20%20EUV%5B%22EUV%20%E5%88%87%20%2F%20%E5%9D%97%20%2F%20%E5%AD%94%22%5D%20--%3E%20GRID%0A%20%20GRID%20--%3E%20DEV%5B%22%E5%99%A8%E4%BB%B6%E8%BF%9E%E9%80%9A%22%5D%0A%20%20HY%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20EUV%2B%E8%87%AA%E5%AF%B9%E5%87%86%E6%B7%B7%E5%90%88%22%5D%20--%3E%20L1D%0A%20%20HY%20--%3E%20EUV%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"自对准线把最紧的周期误差从 overlay 挪到薄膜；EUV 切把最紧的二维终止从浸没多重着色挪到单次（或少次）短波长。两者各买各的：\\(k_1\\) 地板对长直线和切孔不是同一句。EUV 切的随机缺孔、剂量，是胶与源的账；线的 walking 是薄膜的账。互补意味着失效模式并列，不是互相消灭。",-1)),a[5]||(a[5]=E("p",null,"跨波长套刻：浸没栅的指纹与 EUV 场畸变不同，匹配项回到套刻预算课。High-NA EUV 以后切的窗会再变，仍不自动取消 spacer 线——公开策略按层演进，本课不预支时间表。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"互补式也曾在纯 193i 时代被谈论（浸没线 + 浸没切）。EUV 进切层，是短波长去补切的 \\(k_1\\)，不是新发明一种几何。几何是 1D+cut；新的是谁曝光切。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：walking 指芯轴侧与间隙侧两套间隔不等，奇偶间距一宽一窄地交替、平均节距却不动的现象；成因在薄膜与芯轴 CD，所以它记在薄膜工艺的账上，而不在光学的 overlay 账上。")],-1)),(l(),o(n,null,{default:e(()=>[A(r,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20LINE%5B%22SAQP%20%E7%BA%BF%3A%20%E5%91%A8%E6%9C%9F%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20WALK%5B%22walking%20%E4%BC%AA%E7%BA%BF%3A%20%E8%96%84%E8%86%9C%E7%9A%84%E8%B4%A6%22%5D%0A%20%20CUT%5B%22EUV%20%E5%88%87%3A%20%E4%BA%8C%E7%BB%B4%E7%BB%88%E6%AD%A2%22%5D%20--%3E%20MISS%5B%22%E7%BC%BA%E5%AD%94%E4%B8%8E%E5%89%82%E9%87%8F%3A%20%E8%83%B6%E4%B8%8E%E6%BA%90%E7%9A%84%E8%B4%A6%22%5D%0A%20%20OV%5B%22%E6%B5%B8%E6%B2%A1%E6%A0%85%20%C3%97%20EUV%20%E5%9C%BA%22%5D%20--%3E%20OVL%5B%22%E8%B7%A8%E6%B3%A2%E9%95%BF%E5%A5%97%E5%88%BB%3A%20%E9%A2%84%E7%AE%97%E7%9A%84%E8%B4%A6%22%5D%0A%20%20WALK%20--%3E%20INTER%5B%22%E5%B1%82%E7%AA%97%E5%8F%A3%20%3D%20%E4%B8%89%E6%9C%AC%E8%B4%A6%E7%9A%84%E4%BA%A4%E9%9B%86%22%5D%0A%20%20MISS%20--%3E%20INTER%0A%20%20OVL%20--%3E%20INTER%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编某代金属有几张 EUV 版，不编替换几张 DUV 之后的 wph 变化。不把 complementary 写成商标或唯一专利路径——它是公开层策略语言。纯 EUV 二维、EUV LELE、EUV+SADP mandrel 仍与互补式并存，按层选。</p><p>后课进入 EUV 光源与机台时，本课的切层只是那些光子的一个用户：剂量与随机在切孔上往往比在长直线上更苛刻，但那是胶与随机课，不在这里用产能数字代替。SAQP 加切断已经把几何钉成 1D+cut；本课只换「谁曝光切」，不把几何重讲成新发明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>互补式 EUV：1D 自对准密线 + EUV 切/块/孔，按层声明谁印线。</li><li>它是混合策略的一种公开分法，不是整片单次 EUV。</li><li>失效模式并列：walking 在线，随机与套刻在切。</li><li>不编产能、片成本、良率；只保留分工语言。</li><li>几何仍是 1D+cut；新的是谁曝光切，不是新发明一种图形。</li><li>跨波长套刻匹配进预算；节点名仍不是波长。</li><li>切孔剂量与随机往往比长直线更苛刻，不在这里用产能数字代替。</li><li>出处：先进节点 complementary lithography / EUV cut-block 的公开层策略表述。</li></ul>',5))])}const S=s(V,[["render",d]]);export{P as __pageData,S as default};
